def sha(b):return hashlib.sha256(b).hexdigest()
def main():
 root=Path(__file__).resolve().parent
 python=root/'.venv/bin/python'
 if not python.exists() or not (root/'backend/market_lab/api.py').exists():
  raise SystemExit('STOP: copy into ~/RB-ITOS-AI; project or venv missing')
 decoded={p:zlib.decompress(base64.b85decode(x)) for p,x in PAYLOAD.items()}
 changes={}
 for rel,want in BASELINE.items():
  target=root/rel
  if not target.is_file():raise SystemExit(f'STOP: {rel} missing; nothing changed')
  got=sha(target.read_bytes())
  if got==sha(decoded[rel]):continue
  if got!=want:raise SystemExit(f'STOP: {rel} differs from reviewed baseline; nothing changed')
  changes[rel]=decoded[rel]
 for rel in FRESH:
  target=root/rel
  if target.exists():
   if sha(target.read_bytes())!=sha(decoded[rel]):raise SystemExit(f'STOP: {rel} exists with different contents; nothing changed')
  else:changes[rel]=decoded[rel]
 if not changes:print('Already applied');return
 backup=root/'data/backups'/('observation-foundation-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ'))
 backup.mkdir(parents=True,exist_ok=False)
 for rel,data in changes.items():
  target=root/rel
  if target.exists():
   saved=backup/rel;saved.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(target,saved)
  target.parent.mkdir(parents=True,exist_ok=True)
  staged=target.with_name(target.name+'.observation-foundation.tmp');staged.write_bytes(data);staged.replace(target)
 checks=[
  [str(python),'-m','pytest','-q',
   'tests/test_live_loading_integrity_guard.py',
   'tests/test_hilega_milega_option_shadow_lifecycle_v1.py',
   'tests/test_hilega_milega_historical_replay_v1.py',
   'tests/test_hilega_mtf_alignment_research_v1.py',
   'tests/test_observation_fill_risk_research.py',
   'tests/test_midpoint_v57_1_terminal_candle_parity.py',
   'tests/test_midpoint_m3b_live_shadow_v1.py',
   'tests/test_hilega_directional_candle_ui_v1.py',
   'tests/test_hilega_directional_live_shadow_ui_v1.py'],
  ['git','diff','--check'],
 ]
 try:
  for cmd in checks:
   print('Running:',' '.join(cmd),flush=True)
   subprocess.run(cmd,cwd=root,check=True)
 except (subprocess.CalledProcessError,OSError) as exc:
  for rel in reversed(list(changes)):
   saved=backup/rel
   if saved.exists():shutil.copy2(saved,root/rel)
   else:(root/rel).unlink(missing_ok=True)
  print('STOP: validation failed; source restored; API and workers untouched',file=sys.stderr)
  raise SystemExit(1) from exc
 print('PASS: source validation complete. API and workers were not restarted.')
 print('Backup:',backup)
if __name__=='__main__':main()
